{
  "name": "loss_ranking_tanh_advantage",
  "intuition": "Shift to a ranking-based paradigm using a tanh nonlinearity on the advantage gap to scale the margin between winning and losing log probabilities, promoting smooth margin-aware ranking losses.",
  "pseudocode": "margin = tanh(beta * advantage_gap)\nloss = mean(weight * max(0, margin - (log_prob_w - log_prob_l)))",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "relu_tanh_margin",
    "agg_family": "mean",
    "constraint_family": "nonneg_margin"
  },
  "operators_used": ["tanh", "max", "sub", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    advantage_gap = batch['advantage_gap']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.0)))\n    margin = ops.tanh(ops.mul(beta, advantage_gap))\n    diff = ops.sub(margin, ops.sub(lpw, lpl))\n    relu_diff = ops.max(diff, ops.zeros_like(diff))\n    loss = ops.mul(weight, relu_diff)\n    return ops.mean(loss)"
}

{
  "name": "loss_advantage_gap_margin_tanh",
  "intuition": "Use a margin-based pairwise loss with a smooth tanh activation on the scaled advantage gap, directly encouraging margin separation proportional to the advantage difference, instead of log-prob gaps or cost gaps.",
  "pseudocode": "loss = mean(weight * relu(margin - tanh(alpha * advantage_gap)))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_margin_penalty"
  },
  "operators_used": ["tanh", "relu", "mean", "mul", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_gap = batch['advantage_gap']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    margin = float(extra.get('margin', extra.get('hyperparams', {}).get('margin', 0.5)))\n    x = ops.tanh(ops.mul(alpha, adv_gap))\n    penalty = ops.relu(ops.sub(margin, x))\n    if weight is not None:\n        penalty = ops.mul(penalty, weight)\n    return penalty.mean()"
}

{
  "name": "pairwise_cost_gap_pref_loss",
  "intuition": "This loss emphasizes the difference in cost gap between pairs, encouraging the model to prefer sequences with smaller cost gaps, which aligns with optimizing for lower overall cost differences. Using logsigmoid on the normalized cost gap penalizes large gaps and promotes preference for tighter cost distributions.",
  "pseudocode": "loss = -mean(logsigmoid(-normalize(cost_gap_w - cost_gap_l)))",
  "hyperparams": {
    "paradigm_family": "pairwise_comparison",
    "signal_family": "cost_signal",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "cost_order",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "normalize"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    cost_gap_w = batch['cost_gap']\n    cost_gap_l = batch['cost_gap']\n    # Normalize cost gaps\n    gap_mean = ops.mean([cost_gap_w, cost_gap_l], axis=0)\n    gap_std = ops.sqrt(ops.mean([ops.square(cost_gap_w - gap_mean), ops.square(cost_gap_l - gap_mean)], axis=0)+1e-8)\n    norm_gap_w = ops.div(ops.sub(cost_gap_w, gap_mean), gap_std)\n    norm_gap_l = ops.div(ops.sub(cost_gap_l, gap_mean), gap_std)\n    # Compute pairwise loss\n    loss_vals = ops.slogsigmoid(ops.neg(ops.sub(norm_gap_w, norm_gap_l)))\n    # Weight by importance\n    weight = batch.get('weight', ops.ones_like(loss_vals))\n    weighted_loss = ops.mul(loss_vals, weight)\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss emphasizes reducing the cost gap between preferred and less preferred options by combining log probabilities with cost signals, encouraging the model to favor lower-cost options. The pairwise approach directly models the differences, making it suitable for priority in cost optimization in RL4CO.",
  "pseudocode": "loss = mean over pairs of (-log_prob_w + log_prob_l + alpha * cost_gap) where alpha > 0",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost",
    "link_family": "difference",
    "agg_family": "mean",
    "constraint_family": "monotonic",
    "other_hparams": "alpha=1.0"
  },
  "operators_used": ["logsigmoid", "log", "add", "sub", "mul", "div", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    # Compute pairwise difference in log probabilities\n    logprob_diff = ops.sub(log_prob_w, log_prob_l)\n    loss_terms = ops.add(logprob_diff, ops.mul(alpha, cost_gap))\n    loss = ops.mean(loss_terms)\n    return loss"
}

{
  "name": "pairwise_cost_gap_pref_loss",
  "intuition": "This loss encourages preferences based on the relative difference in cost gaps, focusing on how well the model distinguishes between better and worse options, thus enhancing preference consistency where lower cost gaps are preferred. Using logsigmoid on differences stabilizes the scale and emphasizes relative ordering.",
  "pseudocode": "loss = mean over pairs of -logsigmoid(log_prob_w - log_prob_l + alpha * (cost_gap_w - cost_gap_l))",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "preference",
    "other_hparams": "alpha=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get('alpha', 1.0))\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_gap_w = batch.get('cost_gap', None)\n    cost_gap_l = batch.get('cost_gap', None)\n    weight = batch['weight']\n    difference = ops.sub, ops.sub(log_prob_w, log_prob_l)\n    cost_diff = ops.sub, ops.sub(cost_gap_w, cost_gap_l)\n    scaled_diff = ops.add, difference, ops.mul, alpha, cost_diff\n    loss_vals = ops.neg, ops.logsigmoid, scaled_diff\n    if weight is not None:\n        loss_vals = ops.mul, loss_vals, weight\n    return ops.mean(loss_vals)"
}

{
  "name": "loss_composite_crossover_stabilized",
  "intuition": "Removed unavailable keys 'cost_a' and 'cost_b' from expects to fix static gate failure. Simplified the loss by removing entropy and advantage difference terms that require unavailable keys. Focused on stable margin ranking loss using tanh-scaled margin adjusted by advantage_gap, which is a preferred cheap key. Added clamping on scaled margin input to tanh for numerical stability. Used relu to enforce margin loss positivity and mean aggregation. Kept weighting optional and applied if present.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ],
    "returns": "scalar"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_gap = batch['advantage_gap']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 0.5)))\n    margin = ops.sub(lpw, lpl)\n    # Clamp input to tanh for numerical stability\n    scaled_input = ops.clamp(ops.sub(ops.mul(alpha, margin), ops.mul(alpha * beta, adv_gap)), -10.0, 10.0)\n    scaled_margin = ops.tanh(scaled_input)\n    losses = ops.relu(ops.sub(1.0, scaled_margin))\n    if weight is not None:\n        losses = ops.mul(losses, weight)\n    return ops.mean(losses)"
}

