{
  "name": "loss_logsigmoid_001_normalized_sum",
  "intuition": "Normalize the pairwise log probability difference by the norm of advantage_gap to achieve scale-invariance and stabilize training by preventing large magnitude fluctuations. Clamp the scaled logits difference to [-20,20] to avoid numerical overflow in logsigmoid. Aggregate weighted losses by summation to emphasize total loss over the batch.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    advantage_gap = batch['advantage_gap']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    epsilon = 1e-6\n    norm_factor = ops.max(ops.norm(advantage_gap), epsilon)\n    x = ops.mul(alpha * scale, ops.div(ops.sub(lpw, lpl), norm_factor))\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = ops.neg(ops.logsigmoid(x))\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.sum(loss)",
