  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv = batch['advantage_gap']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 0.5)))\n    clip_val = float(extra.get('clip_val', extra.get('hyperparams', {}).get('clip_val', 10.0)))\n    margin = ops.sub(ops.sub(lpw, lpl), ops.mul(beta, adv))\n    clamped_margin = ops.clamp(margin, -clip_val, clip_val)\n    prob = ops.sigmoid(ops.mul(alpha, clamped_margin))\n    losses = ops.neg(ops.logsigmoid(ops.mul(alpha, clamped_margin)))\n    if weight is not None:\n        losses = ops.mul(losses, weight)\n    return ops.mean(losses)"
}

